package com.logistics.inventory;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import org.springframework.amqp.core.*;import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;
@SpringBootApplication public class InventoryServiceApplication {public static void main(String[]a){SpringApplication.run(InventoryServiceApplication.class,a);} @Bean TopicExchange events(){return new TopicExchange("logistics.events");} @Bean Jackson2JsonMessageConverter jsonConverter(){return new Jackson2JsonMessageConverter();} @Bean Queue orderQueue(){return new Queue("inventory.order-created");} @Bean Binding orderBinding(Queue orderQueue,TopicExchange events){return BindingBuilder.bind(orderQueue).to(events).with("OrderCreated");} @Bean org.springframework.boot.CommandLineRunner seed(InventoryRepository repo){return args->{if(repo.count()==0){repo.save(new InventoryItem("SCN-100",42));repo.save(new InventoryItem("LBL-210",180));repo.save(new InventoryItem("PKG-330",65));repo.save(new InventoryItem("RFID-450",12));}};}}

